   227	        // set is then inexact — the difference must survive as unretried,
   228	        // never be cleared by a later clean pass.
   229	        let represented = (self.failed_paths.len() as u64).saturating_add(self.unretried);
   230	        let all_represented = self.files_failed <= represented;
   231	        if !self.failed_paths_truncated && !self.failed_paths.is_empty() && all_represented {
   232	            return (exact(), false);
   233	        }
   234	        if !self.failed_paths_truncated && !self.failed_paths.is_empty() {
   235	            return (exact(), true);
   236	        }
   237	        let truncated =
   238	            self.failed_paths_truncated || (self.files_failed as usize) > self.failures.len();
   239	        // cr-ecm37-5: a list cut for size still names exactly every file it
   240	        // carries — with the report's names, that is what the pass is given.
   241	        // Given the report's alone, 260 long names, each report entry's path
   242	        // shortened, retried none of the 225 the list carried.
   243	        let mut named = exact();
