   245	        for failure in self
   246	            .failures
   247	            .iter()
   248	            .filter(|failure| !failure.path_shortened)
   249	        {
   250	            match &failure.raw_relative_path {
   251	                Some(raw) => {
   252	                    named.raw.insert(raw.clone());
   253	                }
   254	                None => {
   255	                    named.text.insert(PathBuf::from(&failure.relative_path));
   256	                }
   257	            }
   258	        }
   259	        (named, truncated)
   260	    }
