   262	    /// cr-win-1 / cr-rework-1: the failed paths whose failure left this
   263	    /// run's own incomplete copy at the destination — the exact set the
   264	    /// destination sends beside `failed_paths`, never the capped report.
   265	    fn left_in_place(&self) -> RetrySet {
   266	        RetrySet {
   267	            text: self.left_in_place.iter().map(PathBuf::from).collect(),
   268	            raw: self.left_in_place_raw.iter().cloned().collect(),
   269	        }
   270	    }
