   272	    /// cr-ecm37-3: the failed files whose failure may or may not have left
   273	    /// this run's copy — the destination could not be looked at — by the
   274	    /// report's flag. One whose path the report shortened names no file;
   275	    /// the destination marks the account inexact for it.
   276	    fn left_unknown(&self) -> RetrySet {
   277	        let mut set = RetrySet::default();
   278	        for failure in self
   279	            .failures
   280	            .iter()
   281	            .filter(|failure| failure.left_unknown && !failure.path_shortened)
   282	        {
   283	            match &failure.raw_relative_path {
   284	                Some(raw) => {
   285	                    set.raw.insert(raw.clone());
   286	                }
   287	                None => {
   288	                    set.text.insert(PathBuf::from(&failure.relative_path));
   289	                }
   290	            }
   291	        }
   292	        set
   293	    }
