   295	    /// The set the next pass is given, the leftovers among it, and whether
   296	    /// it is short of the failures (see the retry loop). Under
   297	    /// `--ignore-existing`, a failure whose leftover cannot be classified is
   298	    /// not given: every one past a cut leftover list, and (cr-ecm37-3) each
   299	    /// one the destination could not tell — retried with the flag its
   300	    /// partial would be kept as a file the user put there, retried as a
   301	    /// leftover a file put there since would be overwritten. They stay
   302	    /// reported as not retried.
   303	    fn pass_set(&self, ignore_existing: bool) -> (RetrySet, RetrySet, bool) {
   304	        let (set, truncated) = self.retry_set();
   305	        if !ignore_existing {
   306	            return (set, RetrySet::default(), truncated);
   307	        }
   308	        let left = self.left_in_place().intersection(&set);
   309	        if self.left_in_place_truncated {
   310	            return (left.clone(), left, true);
   311	        }
   312	        let unknown = self.left_unknown().intersection(&set);
   313	        if unknown.is_empty() {
   314	            (set, left, truncated)
   315	        } else {
   316	            (set.difference(&unknown), left, true)
   317	        }
   318	    }
   319	
   330	            raw.push(bytes.clone());
   331	        }
   332	        (failures, paths, raw)
   333	    }
