   335	    /// Fold a second session of the same pass into this report.
   336	    fn merge(&mut self, other: PassFailures) {
   337	        self.files_failed = self.files_failed.saturating_add(other.files_failed);
   338	        self.failures.extend(other.failures);
   339	        self.failed_paths.extend(other.failed_paths);
   340	        self.failed_paths_raw.extend(other.failed_paths_raw);
   341	        self.left_in_place_raw.extend(other.left_in_place_raw);
   342	        self.failed_paths_truncated |= other.failed_paths_truncated;
   343	        self.left_in_place.extend(other.left_in_place);
   344	        self.left_in_place_truncated |= other.left_in_place_truncated;
   345	        self.removed_incomplete.extend(other.removed_incomplete);
   346	        self.removed_incomplete_truncated |= other.removed_incomplete_truncated;
   347	        self.unretried = self.unretried.saturating_add(other.unretried);
   348	        self.withheld.extend(other.withheld);
   349	        self.withheld_paths.extend(other.withheld_paths);
   350	    }
   351	
   352	    /// Mark every remaining failure as one that survived a retry — once:
   353	    /// the report says whether it was marked (D-2026-11-24-1), not its
   354	    /// reasons' words. The ones no pass could reach stay a count,
   355	    /// `unretried`, which the report renders as its own line: never a
   356	    /// failure of a made-up name, which a real file can have (cr-ecm34-7).
   357	    fn mark_retried(&mut self) {
   358	        if std::mem::replace(&mut self.retried, true) {
   359	            return;
   360	        }
   361	        for failure in &mut self.failures {
   362	            failure.reason.push_str(RETRIED_SUFFIX);
   363	        }
   364	    }
   365	
   366	    /// cr-ssc6-1: fold one pass's result over the set it was given. A
   367	    /// pass positively accounts for every path it was asked to retry — a
   368	    /// scoped scan reports what it could not enumerate as that file's
   369	    /// failure (`ManifestComplete.scan_failures`), and the diff/sink
   370	    /// report the rest — so its failure report IS the pending set of the
   371	    /// paths it retried. What the pass was never given (the unnamed
   372	    /// remainder of a truncated set) is carried forward unchanged.
   373	    fn after_pass(
   374	        &self,
   375	        given: &RetrySet,
   376	        truncated: bool,
   377	        mut next: PassFailures,
   378	    ) -> PassFailures {
   379	        let retried = given.len();
   380	        let previously_named = self.files_failed.saturating_sub(self.unretried);
   381	        let not_given = if truncated {
   382	            previously_named.saturating_sub(retried as u64)
   383	        } else {
   384	            0
   385	        };
   386	        next.unretried = self.unretried.saturating_add(not_given);
   387	        next.files_failed = next.files_failed.saturating_add(next.unretried);
   388	        // cr-ecm38-5: those of them this report names go on by name, with
   389	        // their reasons, beside the anonymous remainder.
   390	        next.withheld = self.withheld.clone();
   391	        next.withheld_paths = self.withheld_paths.clone();
   392	        if truncated {
   393	            let was_given = |path: &str, bytes: &[u8]| {
   394	                if bytes.is_empty() {
   395	                    given.text.contains(std::path::Path::new(path))
   396	                } else {
   397	                    given.raw.contains(bytes)
   398	                }
   399	            };
   400	            for (at, path) in self.failed_paths.iter().enumerate() {
   401	                let bytes = self.failed_paths_raw.get(at).cloned().unwrap_or_default();
   402	                if !was_given(path, &bytes) {
   403	                    next.withheld_paths.push((path.clone(), bytes));
   404	                }
   405	            }
   406	            for failure in &self.failures {
   407	                let bytes = failure.raw_relative_path.clone().unwrap_or_default();
   408	                if !failure.path_shortened && !was_given(&failure.relative_path, &bytes) {
   409	                    next.withheld.push(failure.clone());
   410	                }
   411	            }
   412	        }
   413	        // cr-rework-2: a leftover stays this run's own copy for as long as
   414	        // its path keeps failing. A pass that failed it on the source side
   415	        // never touched the copy, so its report — which names no leftover
   416	        // for the path — cannot un-classify it; only a path that succeeded
   417	        // leaves the set. cr-rework-3: nor does one whose copy the pass
   418	        // positively removed — it is an ordinary failure from then on, and
   419	        // a file that appears at the path later is protected by
   420	        // --ignore-existing like any other. If the removed set did not
   421	        // fit, a prior leftover it does not name may or may not still be
   422	        // there: it is carried as neither, and classification is marked
   423	        // incomplete, so the next pass retries only the leftovers it can
   424	        // name and leaves the rest reported as not retried.
   425	        let still_failing: HashSet<&str> = next.failed_paths.iter().map(String::as_str).collect();
   426	        let removed: HashSet<&str> = next.removed_incomplete.iter().map(String::as_str).collect();
   427	        let mut left: HashSet<String> = std::mem::take(&mut next.left_in_place)
   428	            .into_iter()
   429	            .collect();
   430	        let carried: Vec<&String> = self
   431	            .left_in_place
   432	            .iter()
   433	            .filter(|path| still_failing.contains(path.as_str()))
   434	            .filter(|path| !removed.contains(path.as_str()))
   435	            .filter(|path| !left.contains(*path))
   436	            .collect();
   437	        // cr-ecm13-3: the same for the names that are not text, each by
   438	        // its bytes. (What a pass removed is listed by text alone.)
   439	        let still_failing_raw: HashSet<&[u8]> = next
   440	            .failed_paths_raw
   441	            .iter()
   442	            .filter(|raw| !raw.is_empty())
   443	            .map(Vec::as_slice)
   444	            .collect();
   445	        let mut left_raw: HashSet<Vec<u8>> = std::mem::take(&mut next.left_in_place_raw)
   446	            .into_iter()
   447	            .collect();
   448	        let carried_raw: Vec<&Vec<u8>> = self
   449	            .left_in_place_raw
   450	            .iter()
   451	            .filter(|raw| still_failing_raw.contains(raw.as_slice()))
   452	            .filter(|raw| !removed.contains(String::from_utf8_lossy(raw).as_ref()))
   453	            .filter(|raw| !left_raw.contains(*raw))
   454	            .collect();
   455	        let ambiguous =
   456	            next.removed_incomplete_truncated && (!carried.is_empty() || !carried_raw.is_empty());
   457	        if !ambiguous {
   458	            left.extend(carried.into_iter().cloned());
   459	            left_raw.extend(carried_raw.into_iter().cloned());
   460	        }
   461	        let mut left_raw: Vec<Vec<u8>> = left_raw.into_iter().collect();
   462	        left_raw.sort();
   463	        next.left_in_place_raw = left_raw;
   464	        let mut left: Vec<String> = left.into_iter().collect();
   465	        left.sort();
   466	        next.left_in_place = left;
   467	        next.left_in_place_truncated |= self.left_in_place_truncated || ambiguous;
   468	        next
   469	    }
