   471	    /// Write the final state back onto a wire-shaped summary.
   472	    pub(crate) fn apply_to_summary(&self, summary: &mut TransferSummary) {
   676	pub(crate) async fn run_retry_passes_until<F, Fut, I>(
   677	    args: &TransferArgs,
   678	    main: PassFailures,
   679	    mut run: F,
   680	    interrupt: I,
   681	) -> Result<RetryOutcome>
   682	where
   683	    F: FnMut(TransferArgs) -> Fut,
   684	    Fut: Future<Output = Result<PassResult>>,
   685	    I: Future<Output = ()>,
   686	{
   687	    let mut interrupt = std::pin::pin!(interrupt);
   688	    let mut interrupted = false;
   689	    let mut current = main;
   690	    let mut added_files = 0u64;
   691	    let mut added_bytes = 0u64;
   692	    let mut passes_run = 0u32;
   693	    let mut in_stream_carrier_used = false;
   694	    let mut files_resumed = 0u64;
   695	    // A dry run writes nothing, so nothing it reported can converge by
   696	    // retrying; the report stands as the first pass produced it.
   697	    let retries = if args.dry_run { 0 } else { args.retries };
   698	    for pass in 1..=retries {
   699	        if current.files_failed == 0 {
   700	            break;
   701	        }
   702	        // cr-win-1: a retry pass compares exactly as the main pass did —
   703	        // a failed write never leaves a target that looks finished (the
   704	        // sink removes it or holds it one byte off the source's size), so
   705	        // the user's compare is trusted here as on any later run. The one
   706	        // exception is --ignore-existing: a path whose failure left this
   707	        // run's own incomplete copy at the destination exists there now,
   708	        // and that copy is not one the user asked to keep — those paths
   709	        // retry apart, as such (cr-ecm13-1: the end that writes copies to
   710	        // one only if nothing stands there by then, and keeps and
   711	        // reports a file that does). cr-rework-1: they come from the exact set the
   712	        // destination sends beside the failed paths, never the capped
   713	        // report; if even that set did not fit, the paths it does not
   714	        // name cannot be classified — retried with the flag a leftover is
   715	        // skipped and its failure cleared, retried without it a file the
   716	        // user asked to keep is overwritten — so none of them is retried:
   717	        // they stay reported as not retried.
   718	        let (set, left, truncated) = current.pass_set(args.ignore_existing);
   719	        if set.is_empty() {
   720	            // cr-ecm35-7: no pass can start — no failed file could be named
   721	            // for it (a name over the wire's budget, say) — so none of them
   722	            // is retried, and the report says so by its count. Left, the
   723	            // run counted the failures and said nothing of the retry it
   724	            // could not make.
   725	            if passes_run == 0 {
   726	                current.unretried = current.files_failed;
   727	            }
   728	            break;
   729	        }
   730	        let total = retries;
   731	        let n = set.len();
   732	        let given = set.clone();
   733	        tokio::select! {
   734	            biased;
   735	            () = interrupt.as_mut() => {
   736	                interrupted = true;
   737	                break;
   738	            }
   739	            () = wait_before_pass(args, pass) => {}
   740	        }
   741	        if !args.json {
   742	            if truncated {
   743	                eprintln!(
   744	                    "retrying {n} of {} file(s) (pass {pass} of {total}) — the retry set was \
   745	                     truncated to the named report; re-run to converge the rest",
   746	                    current.files_failed
   747	                );
   748	            } else {
   749	                eprintln!("retrying {n} file(s) (pass {pass} of {total})");
   750	            }
   751	        }
   752	        blit_core::remote::instrumentation::record_retry_pass(u64::from(pass));
   753	        let mut pass_args = args.clone();
   754	        pass_args.retry_pass = Some((pass, total, n));
   755	        // JOB_LOGS jl-2: each pass is a phase of the run's log.
   756	        let pass_phase = format!("retry pass {pass} of {total}");
   757	        if let Some(run) = &args.run {
   758	            run.record(blit_core::job_log::EventBody::Phase {
   759	                name: pass_phase.clone(),
   760	                state: blit_core::job_log::PhaseState::Start,
   761	            })
   762	            .await;
   763	        }
   764	        // win-1: one heap allocation per pass keeps the pass's session
   765	        // out of this loop's state and its caller's frame.
   766	        let pass_run = async {
   767	            if left.is_empty() {
   768	                set.limit(&mut pass_args);
   769	                Box::pin(run(pass_args)).await
   770	            } else {
   771	                let rest = set.difference(&left);
   772	                let mut left_args = pass_args.clone();
   773	                left.limit(&mut left_args);
   774	                // cr-ecm12-2: said to be this run's own copies, with the
   775	                // option still on. Run with it off, the pass replaced
   776	                // whatever stood at these paths by then.
   777	                left_args.retry_left = true;
   778	                let mut result = Box::pin(run(left_args)).await?;
   779	                if !rest.is_empty() {
   780	                    rest.limit(&mut pass_args);
   781	                    result.merge(Box::pin(run(pass_args)).await?);
   782	                }
   783	                Ok(result)
   784	            }
   785	        };
   786	        // Dropping a pass cut short ends its session; the sink's guards
   787	        // settle any record it had open.
   788	        let result = tokio::select! {
   789	            biased;
   790	            () = interrupt.as_mut() => {
   791	                interrupted = true;
   792	                break;
   793	            }
   794	            result = pass_run => result?,
   795	        };
   796	        if let Some(run) = &args.run {
   797	            run.record(blit_core::job_log::EventBody::Phase {
   798	                name: pass_phase,
   799	                state: blit_core::job_log::PhaseState::End,
   800	            })
   801	            .await;
   802	        }
   803	        added_files = added_files.saturating_add(result.files_transferred);
   804	        added_bytes = added_bytes.saturating_add(result.bytes_transferred);
   805	        in_stream_carrier_used |= result.in_stream_carrier_used;
   806	        files_resumed = files_resumed.saturating_add(result.files_resumed);
   807	        current = current.after_pass(&given, truncated, result.failures);
   808	        passes_run = pass;
   809	    }
   810	    if passes_run > 0 {
   811	        current.mark_retried();
   812	    }
   813	    Ok(RetryOutcome {
   814	        added_files,
   815	        added_bytes,
   816	        final_failures: current,
   817	        passes_run,
   818	        in_stream_carrier_used,
   819	        files_resumed,
   820	        interrupted,
   821	    })
   822	}
