   825	/// recorded to the diagnostics counter file (when one is installed);

   557	/// `MAXSYMLINKS` — 32.
   558	#[cfg(unix)]
   559	pub(crate) const MAX_FOLLOWED_LINKS: usize = if cfg!(target_os = "linux") { 40 } else { 32 };
