   561	/// [`Resolved`]: the place `dst` names, `within` the destination's root
   562	/// when one is given.
   563	#[cfg(unix)]
   564	pub(crate) fn resolve_destination(dst: &Path, within: Option<&super::Within>) -> Result<Resolved> {
