   568	/// [`resolve_destination`], the chain of links at the name followed only
   569	/// when `follow`: a name to be made is never followed.
   570	///
   571	/// cr-ecm38-2: on Linux, with the root held, from the directory the transfer
   572	/// holds ([`resolve_beneath`]) — never by its path, which a directory put in
   573	/// the root's place since names instead.
   574	#[cfg(unix)]
   575	pub(crate) fn resolve_destination_following(
   576	    dst: &Path,
   577	    within: Option<&super::Within>,
   578	    follow: bool,
   579	) -> Result<Resolved> {
   580	    // cr-ecm24-6: a name typed as a directory — with a `/` or `/.` after it,
   581	    // as typed or as a link of the chain names it — is no place for a file:
   582	    // its last name taken, `absent/` was made a regular file `absent`.
   583	    let not_a_file = || {
   584	        Err(std::io::Error::from_raw_os_error(libc::ENOTDIR))
   585	            .with_context(|| format!("putting a fresh partial in place of {}", dst.display()))
   586	    };
   587	    if typed_as_directory(dst) {
   588	        return not_a_file();
   589	    }
   590	    #[cfg(target_os = "linux")]
   591	    if let Some(resolved) = within.and_then(|within| resolve_beneath(within, dst, follow)) {
   592	        let resolved = resolved.map_err(|error| {
   593	            if error.raw_os_error() == Some(libc::ENOTDIR) && follow {
   594	                eyre::Report::new(error).wrap_err(format!(
   595	                    "putting a fresh partial in place of {}",
   596	                    dst.display()
   597	                ))
   598	            } else {
   599	                eyre::Report::new(error).wrap_err(format!("resolving {}", dst.display()))
   600	            }
   601	        })?;
   602	        after_a_destination_is_resolved(dst);
   603	        return Ok(resolved);
   604	    }
   605	    resolve_by_path(dst, within.map(super::Within::path), follow)
   606	}
   607	
   608	/// [`resolve_destination_following`] by the path: the chain followed by its
   609	/// names, the directory it ends in canonicalized and checked within `within`
   610	/// (the root's canonical path), and held — where no root's directory is held
   611	/// to walk from, and off Linux.
   612	#[cfg(unix)]
   613	pub(crate) fn resolve_by_path(dst: &Path, within: Option<&Path>, follow: bool) -> Result<Resolved> {
   614	    let not_a_file = || {
   615	        Err(std::io::Error::from_raw_os_error(libc::ENOTDIR))
   616	            .with_context(|| format!("putting a fresh partial in place of {}", dst.display()))
   617	    };
   618	    if typed_as_directory(dst) {
   619	        return not_a_file();
   620	    }
   621	    let mut target = dst.to_path_buf();
   622	    let mut links = 0;
   623	    while follow
   624	        && std::fs::symlink_metadata(&target).is_ok_and(|there| there.file_type().is_symlink())
   625	    {
   626	        // As many as opening the name would follow — the system's own limit
   627	        // (cr-ecm36-8).
   628	        links += 1;
   629	        if links > MAX_FOLLOWED_LINKS {
   630	            eyre::bail!("{} is a chain of too many links", dst.display());
   631	        }
   632	        let named = std::fs::read_link(&target)
   633	            .with_context(|| format!("reading the link {}", target.display()))?;
   634	        if typed_as_directory(&named) {
   635	            return not_a_file();
   636	        }
   637	        target = match target.parent() {
   638	            Some(parent) if named.is_relative() => parent.join(named),
   639	            _ => named,
   640	        };
   641	    }
   642	    let Some(name) = target.file_name().map(std::ffi::OsStr::to_os_string) else {
   643	        eyre::bail!("{} names no file", dst.display());
   644	    };
   645	    // cr-ecm23-3: the partial is had in the directory the chain ends in,
   646	    // HELD: found by its path with no link in it, that directory lies
   647	    // within the destination — a link there to a name outside it made the
   648	    // file outside — and it is opened from `/` one name at a time, never
   649	    // through a link, so a folder on its way replaced since cannot move
   650	    // where the file is made or named.
   651	    let parent = match target.parent() {
   652	        Some(parent) if !parent.as_os_str().is_empty() => parent.to_path_buf(),
   653	        _ => std::path::PathBuf::from("."),
   654	    };
